const (
	farePerMinute = 1.50
	minimumFare   = 3.50
)

// ComputeFare returns the fare in dollars for a trip with the given route ETA:
// $1.50 per minute, with a minimum of $3.50, rounded to the nearest cent.
func ComputeFare(eta time.Duration) float64 {
	fare := eta.Minutes() * farePerMinute
	if fare < minimumFare {
		fare = minimumFare
	}
	return math.Round(fare*100) / 100
}

