package location

import (
	"context"
	"database/sql"
	"errors"
	"time"

	"github.com/go-sql-driver/mysql"
	"go.uber.org/zap"
)

// ErrRideNotFound is returned when updating a ride history entry that doesn't exist.
var ErrRideNotFound = errors.New("ride history entry not found")

// The ride_history table is created independently of the (seeded) locations
// table, so databases created before this table existed pick it up without
// re-running the locations seed.
const rideHistorySchema = `
CREATE TABLE IF NOT EXISTS ride_history
(
    id bigint unsigned NOT NULL AUTO_INCREMENT,
    pickup_name varchar(255) NOT NULL,
    dropoff_name varchar(255) NOT NULL,
    request_time datetime(3) NOT NULL,
    driver_plate varchar(64) NULL,
    fare decimal(10,2) NULL,

    PRIMARY KEY (id),
    KEY request_time (request_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
`

const rideHistoryColumns = "id, pickup_name, dropoff_name, request_time, driver_plate, fare"

func (d *database) setupRideHistory() error {
	_, err := d.db.Exec(rideHistorySchema)
	return err
}

// rideRetry reports whether a ride_history query that failed with err should
// be retried, creating the ride_history table if it turned out to be missing.
func (d *database) rideRetry(err error) bool {
	var mysqlErr *mysql.MySQLError
	if !errors.As(err, &mysqlErr) || mysqlErr.Number != 1146 {
		return false
	}
	if err := d.setupRideHistory(); err != nil {
		d.logger.Bg().Error("cannot create ride_history table", zap.Error(err))
		return false
	}
	return true
}

type rideScanner interface {
	Scan(dest ...any) error
}

func scanRide(row rideScanner) (*RideHistoryEntry, error) {
	var (
		e     RideHistoryEntry
		plate sql.NullString
		fare  sql.NullFloat64
	)
	if err := row.Scan(&e.ID, &e.PickupLocation, &e.DropoffLocation, &e.RequestTime, &plate, &fare); err != nil {
		return nil, err
	}
	if plate.Valid {
		e.DriverPlate = &plate.String
	}
	if fare.Valid {
		e.Fare = &fare.Float64
	}
	return &e, nil
}

// ListRideHistory returns the most recent limit rides (newest first) and the
// total number of rides stored.
func (d *database) ListRideHistory(ctx context.Context, limit int) (*RideHistoryList, error) {
	d.logger.For(ctx).Info("Loading ride history", zap.Int("limit", limit))

	list, err := d.listRideHistory(ctx, limit)
	if err != nil && d.rideRetry(err) {
		list, err = d.listRideHistory(ctx, limit)
	}
	return list, err
}

func (d *database) listRideHistory(ctx context.Context, limit int) (*RideHistoryList, error) {
	list := &RideHistoryList{Rides: []RideHistoryEntry{}}
	if err := d.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM ride_history").Scan(&list.Total); err != nil {
		return nil, err
	}

	rows, err := d.db.QueryContext(ctx,
		"SELECT "+rideHistoryColumns+" FROM ride_history ORDER BY request_time DESC, id DESC LIMIT ?", limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		e, err := scanRide(rows)
		if err != nil {
			return nil, err
		}
		list.Rides = append(list.Rides, *e)
	}
	return list, rows.Err()
}

// CreateRideHistory stores a new ride without driver and fare, and returns it.
func (d *database) CreateRideHistory(ctx context.Context, req *CreateRideHistoryRequest) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Creating ride history entry",
		zap.String("pickup", req.PickupLocation), zap.String("dropoff", req.DropoffLocation))

	requestTime := req.RequestTime
	if requestTime.IsZero() {
		requestTime = time.Now()
	}
	requestTime = requestTime.UTC().Truncate(time.Millisecond)

	const query = "INSERT INTO ride_history (pickup_name, dropoff_name, request_time) VALUES (?, ?, ?)"
	res, err := d.db.ExecContext(ctx, query, req.PickupLocation, req.DropoffLocation, requestTime)
	if err != nil && d.rideRetry(err) {
		res, err = d.db.ExecContext(ctx, query, req.PickupLocation, req.DropoffLocation, requestTime)
	}
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	return &RideHistoryEntry{
		ID:              id,
		PickupLocation:  req.PickupLocation,
		DropoffLocation: req.DropoffLocation,
		RequestTime:     requestTime,
	}, nil
}

// UpdateRideHistory records the assigned driver plate and fare of a ride and
// returns the updated entry. It returns ErrRideNotFound for an unknown id.
func (d *database) UpdateRideHistory(ctx context.Context, req *UpdateRideHistoryRequest) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Updating ride history entry",
		zap.Int64("id", req.ID), zap.String("plate", req.DriverPlate), zap.Float64("fare", req.Fare))

	const query = "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?"
	_, err := d.db.ExecContext(ctx, query, req.DriverPlate, req.Fare, req.ID)
	if err != nil && d.rideRetry(err) {
		_, err = d.db.ExecContext(ctx, query, req.DriverPlate, req.Fare, req.ID)
	}
	if err != nil {
		return nil, err
	}

	// MySQL reports 0 affected rows when the values are unchanged, so look the
	// row up to tell "not found" apart from "already up to date".
	e, err := scanRide(d.db.QueryRowContext(ctx,
		"SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", req.ID))
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrRideNotFound
	}
	return e, err
}

