	for rows.Next() {
		e, err := scanRide(rows)
		if err != nil {
			return nil, err
		}
		list.Rides = append(list.Rides, *e)
	}
	return list, rows.Err()
}

// CreateRideHistory stores a new ride without driver and fare, and returns it.
func (d *database) CreateRideHistory(ctx context.Context, req *CreateRideHistoryRequest) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Creating ride history entry",
		zap.String("pickup", req.PickupLocation), zap.String("dropoff", req.DropoffLocation))

	requestTime := req.RequestTime
	if requestTime.IsZero() {
		requestTime = time.Now()
	}
	requestTime = requestTime.UTC().Truncate(time.Millisecond)

	const query = "INSERT INTO ride_history (pickup_name, dropoff_name, request_time) VALUES (?, ?, ?)"
	res, err := d.db.ExecContext(ctx, query, req.PickupLocation, req.DropoffLocation, requestTime)
	if err != nil && d.rideRetry(err) {
		res, err = d.db.ExecContext(ctx, query, req.PickupLocation, req.DropoffLocation, requestTime)
	}
	if err != nil {
		return nil, err
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, err
	}
	return &RideHistoryEntry{
		ID:              id,
		PickupLocation:  req.PickupLocation,
		DropoffLocation: req.DropoffLocation,
		RequestTime:     requestTime,
	}, nil
}

// UpdateRideHistory records the assigned driver plate and fare of a ride and
// returns the updated entry. It returns ErrRideNotFound for an unknown id.
func (d *database) UpdateRideHistory(ctx context.Context, req *UpdateRideHistoryRequest) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Updating ride history entry",
		zap.Int64("id", req.ID), zap.String("plate", req.DriverPlate), zap.Float64("fare", req.Fare))

	const query = "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?"
	_, err := d.db.ExecContext(ctx, query, req.DriverPlate, req.Fare, req.ID)
	if err != nil && d.rideRetry(err) {
		_, err = d.db.ExecContext(ctx, query, req.DriverPlate, req.Fare, req.ID)
	}
	if err != nil {
		return nil, err
	}

	// MySQL reports 0 affected rows when the values are unchanged, so look the
	// row up to tell "not found" apart from "already up to date".
	e, err := scanRide(d.db.QueryRowContext(ctx,
		"SELECT "+rideHistoryColumns+" FROM ride_history WHERE id = ?", req.ID))
