package location

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"net/http"
	"strconv"
	"unicode/utf8"

	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/httperr"
)

const (
	defaultRideHistoryLimit = 50
	maxRideHistoryLimit     = 500

	maxLocationNameLen = 255
	maxDriverPlateLen  = 64
	maxFare            = 99999999.99 // decimal(10,2)
	maxBodyBytes       = 1 << 20
)

func (s *Server) listRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	limit := defaultRideHistoryLimit
	if v := r.URL.Query().Get("limit"); v != "" {
		var err error
		limit, err = strconv.Atoi(v)
		if err != nil || limit < 1 || limit > maxRideHistoryLimit {
			err = fmt.Errorf("parameter 'limit' must be an integer between 1 and %d", maxRideHistoryLimit)
			httperr.HandleError(w, err, http.StatusBadRequest)
			return
		}
	}

	list, err := s.database.ListRideHistory(ctx, limit)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot get ride history", zap.Error(err))
		return
	}
	s.writeJSON(w, r, list)
}

func (s *Server) createRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var req CreateRideHistoryRequest
	err := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes)).Decode(&req)
	if err == nil {
		err = validateCreateRide(&req)
	}
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	entry, err := s.database.CreateRideHistory(ctx, &req)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}
	s.writeJSON(w, r, entry)
}

func (s *Server) updateRideHistory(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	var req UpdateRideHistoryRequest
	err := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes)).Decode(&req)
	if err == nil {
		err = validateUpdateRide(&req)
	}
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	entry, err := s.database.UpdateRideHistory(ctx, &req)
	if errors.Is(err, ErrRideNotFound) {
		httperr.HandleError(w, err, http.StatusNotFound)
		return
	}
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}
	s.writeJSON(w, r, entry)
}

func (s *Server) writeJSON(w http.ResponseWriter, r *http.Request, v any) {
	data, err := json.Marshal(v)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(r.Context()).Error("cannot marshal response", zap.Error(err))
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func validateCreateRide(req *CreateRideHistoryRequest) error {
	if req.PickupLocation == "" || req.DropoffLocation == "" {
		return errors.New("'pickupLocation' and 'dropoffLocation' are required")
	}
	if utf8.RuneCountInString(req.PickupLocation) > maxLocationNameLen ||
		utf8.RuneCountInString(req.DropoffLocation) > maxLocationNameLen {
		return fmt.Errorf("location names can be at most %d characters", maxLocationNameLen)
	}
	return nil
}

func validateUpdateRide(req *UpdateRideHistoryRequest) error {
	if req.ID <= 0 {
		return errors.New("'id' is required")
	}
	if req.DriverPlate == "" {
		return errors.New("'driverPlate' is required")
	}
	if utf8.RuneCountInString(req.DriverPlate) > maxDriverPlateLen {
		return fmt.Errorf("'driverPlate' can be at most %d characters", maxDriverPlateLen)
	}
	if math.IsNaN(req.Fare) || req.Fare < 0 || req.Fare > maxFare {
		return fmt.Errorf("'fare' must be between 0 and %.2f", maxFare)
	}
	return nil
}
EOF

