package location

import (
	"math"
	"strings"
	"testing"
)

func TestValidateCreateRide(t *testing.T) {
	tests := []struct {
		name    string
		req     CreateRideHistoryRequest
		wantErr bool
	}{
		{"ok", CreateRideHistoryRequest{PickupLocation: "a", DropoffLocation: "b"}, false},
		{"missing pickup", CreateRideHistoryRequest{DropoffLocation: "b"}, true},
		{"missing dropoff", CreateRideHistoryRequest{PickupLocation: "a"}, true},
		{"name too long", CreateRideHistoryRequest{PickupLocation: strings.Repeat("a", 256), DropoffLocation: "b"}, true},
	}
	for _, tt := range tests {
		if err := validateCreateRide(&tt.req); (err != nil) != tt.wantErr {
			t.Errorf("%s: err = %v, wantErr %v", tt.name, err, tt.wantErr)
		}
	}
}

func TestValidateUpdateRide(t *testing.T) {
	tests := []struct {
		name    string
		req     UpdateRideHistoryRequest
		wantErr bool
	}{
		{"ok", UpdateRideHistoryRequest{ID: 1, DriverPlate: "T712345C", Fare: 3.5}, false},
		{"zero fare", UpdateRideHistoryRequest{ID: 1, DriverPlate: "T712345C"}, false},
		{"missing id", UpdateRideHistoryRequest{DriverPlate: "T712345C", Fare: 3.5}, true},
		{"missing plate", UpdateRideHistoryRequest{ID: 1, Fare: 3.5}, true},
		{"negative fare", UpdateRideHistoryRequest{ID: 1, DriverPlate: "x", Fare: -1}, true},
		{"nan fare", UpdateRideHistoryRequest{ID: 1, DriverPlate: "x", Fare: math.NaN()}, true},
		{"huge fare", UpdateRideHistoryRequest{ID: 1, DriverPlate: "x", Fare: 1e12}, true},
	}
	for _, tt := range tests {
		if err := validateUpdateRide(&tt.req); (err != nil) != tt.wantErr {
			t.Errorf("%s: err = %v, wantErr %v", tt.name, err, tt.wantErr)
		}
	}
}
EOF
